import { PaletteOptions } from "@mui/material/styles";

const palette: PaletteOptions = {
  mode: "dark",

  // Eskom Official Brand Colors
  primary: {
    main: "#E2231A", // Eskom Red
    light: "#FF4842",
    dark: "#B01B14",
    contrastText: "#FFFFFF",
  },

  secondary: {
    main: "#000000", // Eskom Black
    light: "#1A1A1A",
    dark: "#000000",
    contrastText: "#FFFFFF",
  },

  // Accent colors for data visualization
  success: {
    main: "#00C853", // Bright green for positive metrics
    light: "#69F0AE",
    dark: "#00A843",
  },

  warning: {
    main: "#FFD600", // Bright yellow for warnings
    light: "#FFEA00",
    dark: "#FFC400",
  },

  error: {
    main: "#E2231A", // Eskom Red for errors
    light: "#FF4842",
    dark: "#B01B14",
  },

  info: {
    main: "#2196F3", // Blue for informational
    light: "#64B5F6",
    dark: "#1976D2",
  },

  // Dark theme backgrounds
  background: {
    default: "#0A0A0A", // Deep black
    paper: "#1A1A1A", // Slightly lighter black for cards
  },

  text: {
    primary: "#FFFFFF",
    secondary: "rgba(255, 255, 255, 0.7)",
    disabled: "rgba(255, 255, 255, 0.38)",
  },

  divider: "rgba(255, 255, 255, 0.12)",

  grey: {
    50: "#FAFAFA",
    100: "#F5F5F5",
    200: "#EEEEEE",
    300: "#E0E0E0",
    400: "#BDBDBD",
    500: "#9E9E9E",
    600: "#757575",
    700: "#424242",
    800: "#212121",
    900: "#0A0A0A",
  },

  // Custom colors for Eskom dashboard
  action: {
    active: "#E2231A",
    hover: "rgba(226, 35, 26, 0.08)",
    selected: "rgba(226, 35, 26, 0.16)",
    disabled: "rgba(255, 255, 255, 0.26)",
    disabledBackground: "rgba(255, 255, 255, 0.12)",
  },
};

export default palette;
